# Sticky canary routing: hash the user id so the same user always sees the same model.
import hashlib

def bucket(user_id, salt="rollout-1"):
    h = hashlib.sha256((salt + user_id).encode()).hexdigest()
    return int(h, 16) % 100                   # stable number 0..99

def model_for(user_id, canary_pct):
    return "new" if bucket(user_id) < canary_pct else "old"

users = [f"user{i}" for i in range(1000)]
for pct in (5, 20):
    share = sum(model_for(u, pct) == "new" for u in users) / len(users)
    print(f"canary {pct}%: actual share on new model = {share:.1%}")
# Stickiness: ramping 5% -> 20% only ADDS users, nobody flips back to old.
s5 = {u for u in users if model_for(u, 5) == "new"}
s20 = {u for u in users if model_for(u, 20) == "new"}
print("5% group is a subset of the 20% group:", s5 <= s20)
print("same user twice:", model_for("user7", 20), model_for("user7", 20))
